/* Runs that did not happen, written as logs that did.
 *
 * A scene is generated by driving the real state machine over invented
 * record times and writing what it did. The state lines in a scene are
 * therefore the lines the machine would have written, not lines composed to
 * look right, so a scene cannot disagree with the program it is testing.
 */

#include "p13.h"

#include <string.h>

#define P13_SCENE_EVENTS_MAX 1024
#define P13_TICK_S 1.0

typedef struct {
    double t;
    const char *tag;
} p13_point;

void p13_synth_init(p13_synth *s)
{
    if (s == NULL)
        return;
    s->minutes = 10.0;
    s->primary_every_s = 15.0;
    s->backup_every_s = 120.0;
    s->outage_start_s = 120.0;
    s->outage_end_s = 240.0;
}

static bool primary_sends(p13_scene scene, const p13_synth *c, double t)
{
    switch (scene) {
    case P13_SCENE_STEADY:
        return true;
    case P13_SCENE_OUTAGE:
        return !(t > c->outage_start_s && t < c->outage_end_s);
    case P13_SCENE_SHORT_GAP:
        /* One sample missing, which is inside the window and must not flip
         * anything. This is the case a shorter window would get wrong. */
        return !(t > c->outage_start_s && t < c->outage_start_s + c->primary_every_s * 1.5);
    case P13_SCENE_NO_RETURN:
        return t <= c->outage_start_s;
    case P13_SCENE_BACKUP_ONLY:
        return false;
    }
    return true;
}

p13_status p13_scene_write(p13_scene scene, const p13_synth *cfg,
                           double window_s, const char *path)
{
    if (cfg == NULL || path == NULL)
        return P13_E_ARG;
    if (cfg->primary_every_s <= 0.0 || cfg->backup_every_s <= 0.0)
        return P13_E_ARG;

    static p13_point pts[P13_SCENE_EVENTS_MAX];
    size_t n = 0;
    const double span = cfg->minutes * 60.0;

    /* Counted rather than accumulated, so the hundredth sample is at a
     * hundred intervals exactly and a long run does not drift off its own
     * schedule. */
    for (uint32_t k = 0; n < P13_SCENE_EVENTS_MAX; k++) {
        double t = (double)k * cfg->primary_every_s;
        if (t > span)
            break;
        if (primary_sends(scene, cfg, t)) {
            pts[n].t = t;
            pts[n].tag = P13_PRIMARY_TAG;
            n++;
        }
    }
    for (uint32_t k = 0; n < P13_SCENE_EVENTS_MAX; k++) {
        double t = (double)k * cfg->backup_every_s;
        if (t > span)
            break;
        pts[n].t = t;
        pts[n].tag = P13_BACKUP_TAG;
        n++;
    }

    /* By time, and by tag within a time so that a run is reproducible. */
    for (size_t i = 1; i < n; i++) {
        p13_point key = pts[i];
        size_t j = i;
        while (j > 0 && (pts[j - 1].t > key.t ||
                        (pts[j - 1].t == key.t &&
                         strcmp(pts[j - 1].tag, key.tag) > 0))) {
            pts[j] = pts[j - 1];
            j--;
        }
        pts[j] = key;
    }

    p13_log log;
    p13_status st = p13_log_open(&log, path);
    if (st != P13_OK)
        return st;

    p13_supervisor sup;
    p13_init(&sup, window_s);
    double clock = 0.0;

    for (size_t i = 0; i < n; i++) {
        while (clock + P13_TICK_S <= pts[i].t) {
            clock += P13_TICK_S;
            if (p13_on_tick(&sup, clock) == P13_EVENT_TO_FAILOVER)
                p13_log_state(&log, clock, P13_FAILOVER,
                              clock - sup.last_primary_at);
        }
        clock = pts[i].t;
        p13_log_record(&log, clock, pts[i].tag);
        if (p13_on_record(&sup, clock, pts[i].tag, NULL) == P13_EVENT_TO_PRIMARY)
            p13_log_state(&log, clock, P13_PRIMARY, 0.0);
    }

    /* The run does not end at the last record. A primary that stops has to
     * be allowed to time out, or a log of an outage would end before the
     * thing it is a log of. */
    while (clock + P13_TICK_S <= span) {
        clock += P13_TICK_S;
        if (p13_on_tick(&sup, clock) == P13_EVENT_TO_FAILOVER)
            p13_log_state(&log, clock, P13_FAILOVER, clock - sup.last_primary_at);
    }

    return p13_log_close(&log);
}
